CREATE TABLE Benchmark_Testing (
    Benchmark_Testing_ID INTEGER PRIMARY KEY,
    Benchmark_Testing_Name VARCHAR(255)
);

CREATE TABLE Unit (
    Benchmark_Testing_ID INTEGER NOT NULL,
    Unit_ID INTEGER PRIMARY KEY,
    Unit_Name VARCHAR(255),
    FOREIGN KEY (Benchmark_Testing_ID) REFERENCES Benchmark_Testing(Benchmark_Testing_ID)
);

CREATE TABLE Customers_Table (
    CustomerID INTEGER PRIMARY KEY,
    Name VARCHAR(255),
    Phone INTEGER
);

CREATE TABLE Airlines_Table (
    AirlineID INTEGER PRIMARY KEY,
    AirlineName VARCHAR(255),
    Route VARCHAR(255),
    Time DATETIME
);

CREATE TABLE CustomerReviews_Table (
    AirlineID INTEGER,
    CustomerID INTEGER,
    ReviewContent VARCHAR(255),
    ReviewGrade FLOAT,
    ReviewID INTEGER PRIMARY KEY
);

CREATE TABLE CustomerBankAccounts_Table (
    AccountID null PRIMARY KEY,
    AccountNumber null,
    Balance null,
    CustomerID null
);

CREATE TABLE Customer (
    Customer_Contact_Information VARCHAR(255),
    Customer_ID INTEGER PRIMARY KEY,
    Customer_Name VARCHAR(255)
);

CREATE TABLE Product (
    Product_ID INTEGER PRIMARY KEY,
    Product_Inventory_Quantity INTEGER,
    Product_Name VARCHAR(255),
    Product_Price FLOAT
);

CREATE TABLE Order (
    Order_ID INTEGER PRIMARY KEY,
    Order_Status VARCHAR(255),
    Ordering_Customer_ID INTEGER NOT NULL,
    FOREIGN KEY (Ordering_Customer_ID) REFERENCES Customer(Customer_ID)
);

CREATE TABLE Ordered_Product (
    Order_ID INTEGER NOT NULL,
    Ordered_Product_ID INTEGER NOT NULL,
    Ordered_Quantity INTEGER,
    PRIMARY KEY (Order_ID, Ordered_Product_ID),
    FOREIGN KEY (Order_ID) REFERENCES Order(Order_ID),
    FOREIGN KEY (Ordered_Product_ID) REFERENCES Product(Product_ID)
);

CREATE TABLE Picking_List (
    Order_ID INTEGER NOT NULL,
    Picking_List_ID INTEGER PRIMARY KEY,
    Picking_Status VARCHAR(255),
    FOREIGN KEY (Order_ID) REFERENCES Order(Order_ID)
);

CREATE TABLE Delivery_Order (
    Delivery_Order_ID INTEGER PRIMARY KEY NOT NULL,
    Delivery_Status VARCHAR(255),
    Delivery_Time DATETIME,
    FOREIGN KEY (Delivery_Order_ID) REFERENCES Order(Order_ID)
);

CREATE TABLE Customer_Invoice (
    Customer_Invoice_ID INTEGER PRIMARY KEY,
    Invoice_Amount FLOAT,
    Invoice_Date DATETIME,
    Order_ID INTEGER NOT NULL,
    FOREIGN KEY (Order_ID) REFERENCES Order(Order_ID)
);

CREATE TABLE Accounts_Receivable_Report (
    Order_ID INTEGER NOT NULL,
    Receivable_Amount FLOAT,
    Report_Date DATETIME,
    Report_ID INTEGER PRIMARY KEY,
    FOREIGN KEY (Order_ID) REFERENCES Order(Order_ID)
);

CREATE TABLE Picked_Product (
    Picked_Product_ID INTEGER NOT NULL,
    Picked_Product_Quantity INTEGER,
    Picking_List_ID INTEGER NOT NULL,
    PRIMARY KEY (Picking_List_ID, Picked_Product_ID),
    FOREIGN KEY (Picked_Product_ID) REFERENCES Product(Product_ID),
    FOREIGN KEY (Picking_List_ID) REFERENCES Picking_List(Picking_List_ID)
);

CREATE TABLE Customer (
    Address VARCHAR(255),
    Contact_Number VARCHAR(255),
    Customer_ID INTEGER PRIMARY KEY,
    Name VARCHAR(255)
);

CREATE TABLE Raw_Material (
    Raw_Material_ID INTEGER PRIMARY KEY,
    Raw_Material_Name VARCHAR(255),
    Specification VARCHAR(255)
);

CREATE TABLE Financial_Record (
    Amount INTEGER,
    Date DATETIME,
    Status VARCHAR(255),
    Transaction_ID INTEGER PRIMARY KEY,
    Transaction_Type VARCHAR(255)
);

CREATE TABLE Supplier (
    Contact_Information VARCHAR(255),
    Supplier_ID INTEGER PRIMARY KEY,
    Supplier_Name VARCHAR(255)
);

CREATE TABLE Pizza_Recipe (
    Raw_Material_ID INTEGER,
    Recipe_ID INTEGER PRIMARY KEY,
    Usage_Amount INTEGER
);

CREATE TABLE Sales_Order (
    Customer_ID INTEGER NOT NULL,
    Expected_Delivery_Date DATETIME,
    Order_ID INTEGER PRIMARY KEY,
    Order_Status VARCHAR(255),
    FOREIGN KEY (Customer_ID) REFERENCES Customer(Customer_ID)
);

CREATE TABLE Purchase_Order (
    Order_Quantity INTEGER,
    Order_Status VARCHAR(255),
    Purchase_Order_ID INTEGER PRIMARY KEY,
    Raw_Material_ID INTEGER NOT NULL,
    Supplied_Quantity INTEGER,
    Supplier_ID INTEGER NOT NULL,
    FOREIGN KEY (Raw_Material_ID) REFERENCES Raw_Material(Raw_Material_ID),
    FOREIGN KEY (Supplier_ID) REFERENCES Supplier(Supplier_ID)
);

CREATE TABLE Product (
    Product_ID INTEGER PRIMARY KEY,
    Product_Name VARCHAR(255),
    Recipe_ID INTEGER NOT NULL,
    FOREIGN KEY (Recipe_ID) REFERENCES Pizza_Recipe(Recipe_ID)
);

CREATE TABLE Production_Plan (
    Order_ID INTEGER NOT NULL,
    Production_Plan_ID INTEGER PRIMARY KEY,
    Production_Status VARCHAR(255),
    FOREIGN KEY (Order_ID) REFERENCES Sales_Order(Order_ID)
);

CREATE TABLE Delivery_Record (
    Delivery_Location VARCHAR(255),
    Delivery_Record_ID INTEGER PRIMARY KEY,
    Delivery_Time DATETIME,
    Order_ID INTEGER NOT NULL,
    Status VARCHAR(255),
    FOREIGN KEY (Order_ID) REFERENCES Sales_Order(Order_ID)
);

CREATE TABLE Inventory_Management (
    Inventory_ID INTEGER PRIMARY KEY,
    Product_ID INTEGER NOT NULL,
    Quantity INTEGER,
    Status VARCHAR(255),
    FOREIGN KEY (Product_ID) REFERENCES Product(Product_ID)
);
